pub(super) fn over(dst: &mut [u8; 4], src: [u8; 4]) {
    let sa = src[3] as u32;
    if sa == 0 {
        return;
    }
    let da = dst[3] as u32;
    let inv = 255 - sa;
    let an = sa * 255 + da * inv;
    for c in 0..3 {
        let n = src[c] as u32 * sa * 255 + dst[c] as u32 * da * inv;
        dst[c] = ((n + an / 2) / an) as u8
    }
    dst[3] = ((an + 127) / 255) as u8
}
