    let fy = sy - y0 as f64;
    let pix = |xx: usize, yy: usize| -> Option<[u8; 4]> {
        let o = yy
            .checked_mul(image.pixels.row_stride)?
            .checked_add(xx.checked_mul(4)?)?;
